import { useEffect, useMemo, useState, type ReactNode } from 'react';
import { BrowserRouter, Link, Route, Routes, useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import { supabase } from '@/lib/supabase';
import { categories, copy, professionals, type Language, type Professional } from '@/data';
import { AirVent, ArrowRight, BadgeCheck, Bell, BriefcaseBusiness, Building2, CalendarDays, CarFront, Check, ChevronDown, ChevronLeft, CircleUserRound, Clock3, Code2, Droplets, Facebook, Filter, Flame, Globe2, Hammer, HardHat, Heart, Home, KeyRound, Leaf, Lightbulb, Linkedin, ListFilter, LockKeyhole, LogIn, Mail, MapPin, Menu, MessageCircle, Moon, Package, Palette, Paintbrush, Phone, Refrigerator, Search, Settings, ShieldCheck, Smartphone, Sparkles, Star, Sun, ThumbsUp, UserPlus, Users, Wrench, X, Zap } from 'lucide-react';

const iconMap: Record<string, typeof Wrench> = { zap: Zap, droplets: Droplets, home: Home, hammer: Hammer, paintbrush: Paintbrush, sparkles: Sparkles, snowflake: AirVent, refrigerator: Refrigerator, 'car-front': CarFront, 'hard-hat': HardHat, leaf: Leaf, 'key-round': KeyRound, bug: Flame, package: Package, laptop: Code2, smartphone: Smartphone };
const Icon = ({ name, size = 20 }: { name: string; size?: number }) => { const Component = iconMap[name] ?? Wrench; return <Component size={size} strokeWidth={1.8} />; };

function App() {
  const [theme, setTheme] = useState<'light' | 'dark'>(() => (localStorage.getItem('kw-theme') as 'light' | 'dark') || 'light');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('kw-language') as Language) || 'en');
  useEffect(() => { document.documentElement.classList.toggle('dark', theme === 'dark'); localStorage.setItem('kw-theme', theme); }, [theme]);
  useEffect(() => { localStorage.setItem('kw-language', language); }, [language]);
  return <BrowserRouter><AppShell theme={theme} language={language} setTheme={setTheme} setLanguage={setLanguage} /></BrowserRouter>;
}

type ShellProps = { theme: 'light' | 'dark'; language: Language; setTheme: (theme: 'light' | 'dark') => void; setLanguage: (language: Language) => void };
const dashboardTabs: Record<string, string[]> = { customer: ['Overview','Find Professionals','My Requests','Favorites','Reviews','My Profile','Settings'], professional: ['Overview','My Profile','Service Requests','My Services','Availability','Reviews','Portfolio','Verification'], admin: ['Dashboard','Users','Professionals','Categories','Requests','Reviews','Verification','Settings'] };
function getDashboardType(pathname: string): keyof typeof dashboardTabs | null { if (pathname.startsWith('/admin')) return 'admin'; if (pathname.startsWith('/professional/dashboard')) return 'professional'; if (pathname.startsWith('/dashboard')) return 'customer'; return null; }

function AppShell({ theme, language, setTheme, setLanguage }: ShellProps) {
  const [menuOpen, setMenuOpen] = useState(false); const t = copy[language];
  const location = useLocation(); const dashboardType = getDashboardType(location.pathname); const [activeTab, setActiveTab] = useState('Overview');
  return <div className="min-h-screen bg-[#f7f5f0] dark:bg-[#101613] transition-colors"><Header theme={theme} language={language} setTheme={setTheme} setLanguage={setLanguage} menuOpen={menuOpen} setMenuOpen={setMenuOpen} dashboardType={dashboardType} activeTab={activeTab} setActiveTab={setActiveTab} /><Routes>
    <Route path="/" element={<HomePage t={t} language={language} />} /><Route path="/categories" element={<CategoriesPage t={t} />} /><Route path="/search" element={<SearchPage />} /><Route path="/professional/:id" element={<ProfessionalPage />} />
    <Route path="/login" element={<AuthPage professional={false} />} /><Route path="/register" element={<AuthPage professional={false} register />} /><Route path="/professional/login" element={<AuthPage professional />} /><Route path="/professional/register" element={<AuthPage professional register />} />
    <Route path="/dashboard/*" element={<Dashboard activeTab={activeTab} setActiveTab={setActiveTab} />} /><Route path="/professional/dashboard/*" element={<ProfessionalDashboard activeTab={activeTab} setActiveTab={setActiveTab} />} /><Route path="/admin/*" element={<AdminDashboard activeTab={activeTab} setActiveTab={setActiveTab} />} />
    <Route path="/about" element={<InfoPage title="About KaamWale" eyebrow="LOCAL, MADE SIMPLE" text="KaamWale brings trusted local services closer to home. We are building a dependable way for customers to discover skilled professionals and for local talent to be seen, valued and chosen." />} /><Route path="/contact" element={<InfoPage title="We are here to help" eyebrow="CONTACT" text="Have a question, suggestion or partnership idea? Our support team is building a helpful, human-first experience for every KaamWale user." />} /><Route path="/privacy" element={<InfoPage title="Privacy, simply explained" eyebrow="PRIVACY" text="This page is a clear placeholder for the final privacy policy. It will explain how account, contact and service-request information is used, protected and retained." />} /><Route path="/terms" element={<InfoPage title="Terms of use" eyebrow="LEGAL" text="This page is a clear placeholder for the final terms and conditions. The final version should be reviewed before launch and will cover marketplace use, professionals and service requests." />} />
  </Routes><Footer t={t} /></div>;
}

function Header({ theme, language, setTheme, setLanguage, menuOpen, setMenuOpen, dashboardType, activeTab, setActiveTab }: ShellProps & { menuOpen: boolean; setMenuOpen: (open: boolean) => void; dashboardType: keyof typeof dashboardTabs | null; activeTab: string; setActiveTab: (tab: string) => void }) {
  const location = useLocation(); const navigate = useNavigate(); const t = copy[language];
  return <header className="sticky top-0 z-40 border-b border-[#e7e3da]/80 bg-[#f7f5f0]/90 dark:bg-[#101613]/90 backdrop-blur-xl"><div className="mx-auto flex h-[76px] max-w-[1240px] items-center justify-between px-5 lg:px-8"><Link to="/" className="flex items-center gap-2.5"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#193c2b] text-[#f6bc55] shadow-sm"><Wrench size={21}/></span><span className="heading text-[21px] font-extrabold tracking-tight text-[#193c2b] dark:text-[#e8f2e8]">Kaam<span className="text-[#de6b35]">Wale</span></span></Link><nav className="hidden items-center gap-7 lg:flex">{t.nav.map((item, i) => <Link key={item} to={['/','/categories','#how','/professional/register','/about'][i]} className={`text-[13px] font-semibold ${location.pathname === ['/','/categories'][i] ? 'text-[#de6b35]' : 'text-[#657168] hover:text-[#193c2b] dark:hover:text-white'}`}>{item}</Link>)}</nav><div className="hidden items-center gap-2.5 lg:flex"><select aria-label="Language" value={language} onChange={e => setLanguage(e.target.value as Language)} className="h-9 rounded-lg border-0 bg-transparent px-2 text-xs font-semibold text-[#657168] outline-none"><option value="en">EN</option><option value="hi">हिंदी</option><option value="hinglish">HINGLISH</option></select><button aria-label="Toggle theme" onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')} className="flex h-9 w-9 items-center justify-center rounded-lg text-[#657168] hover:bg-[#e9e6dd] dark:hover:bg-[#1c2820]">{theme === 'light' ? <Moon size={17}/> : <Sun size={17}/>}</button><Link to="/login" className="ml-1 rounded-lg px-3 py-2 text-sm font-bold text-[#193c2b] dark:text-[#e8f2e8]">Log in</Link><Link to="/register" className="btn-dark rounded-lg px-4 py-2.5 text-sm font-bold">Get started</Link></div><div className="flex items-center gap-2 lg:hidden"><button aria-label="Toggle theme" onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')} className="flex h-9 w-9 items-center justify-center rounded-lg text-[#657168]">{theme === 'light' ? <Moon size={17}/> : <Sun size={17}/>}</button><button aria-label="Open menu" onClick={() => setMenuOpen(!menuOpen)} className="flex h-10 w-10 items-center justify-center rounded-lg bg-[#193c2b] text-white">{menuOpen ? <X size={19}/> : <Menu size={19}/>}</button></div></div>{menuOpen && <div className="border-t border-[#e7e3da] bg-[#f7f5f0] p-5 dark:border-[#28382e] dark:bg-[#101613] lg:hidden"><div className="flex flex-col gap-4">{t.nav.map((item, i) => <Link onClick={() => setMenuOpen(false)} key={item} to={['/','/categories','#how','/professional/register','/about'][i]} className="font-semibold text-[#193c2b] dark:text-white">{item}</Link>)}<div className="flex items-center gap-3 border-t border-[#e7e3da] pt-4 dark:border-[#28382e]"><select value={language} onChange={e => setLanguage(e.target.value as Language)} className="rounded-lg border border-[#dedbd1] bg-transparent px-3 py-2 text-sm"><option value="en">English</option><option value="hi">हिंदी</option><option value="hinglish">Hinglish</option></select><Link to="/login" className="btn-dark rounded-lg px-4 py-2 text-sm">Log in</Link></div></div></div>}{dashboardType && <div className="border-t border-[#e7e3da] dark:border-[#28382e]"><div className="mx-auto flex max-w-[1240px] gap-1 overflow-x-auto px-5 lg:px-8" style={{scrollbarWidth:'none'}}>{dashboardTabs[dashboardType].map(tab => <button key={tab} onClick={() => setActiveTab(tab)} className={`whitespace-nowrap border-b-2 px-3 py-3 text-xs font-bold transition ${activeTab===tab?'border-[#de6b35] text-[#de6b35]':'border-transparent text-[#657168] hover:text-[#193c2b] dark:hover:text-white'}`}>{tab}</button>)}</div></div>}</header>;
}

function SearchBox({ t, compact = false }: { t: typeof copy.en; compact?: boolean }) { const navigate = useNavigate(); const [service, setService] = useState(''); const [location, setLocation] = useState(''); return <div className={`surface flex ${compact ? 'max-w-4xl' : 'max-w-3xl'} flex-col gap-2 rounded-2xl p-2 shadow-[0_16px_45px_rgba(25,60,43,.12)] sm:flex-row`}><div className="flex flex-1 items-center gap-3 rounded-xl px-3 py-2.5"><Search size={19} className="text-[#de6b35]"/><input value={service} onChange={e => setService(e.target.value)} onKeyDown={e => e.key === 'Enter' && navigate(`/search?category=${encodeURIComponent(service)}`)} placeholder={t.service} className="w-full bg-transparent text-sm font-medium outline-none placeholder:text-[#9aa49b]" /></div><div className="hidden w-px bg-[#e8e5dd] sm:block"/><div className="flex flex-1 items-center gap-3 rounded-xl px-3 py-2.5"><MapPin size={19} className="text-[#de6b35]"/><input value={location} onChange={e => setLocation(e.target.value)} onKeyDown={e => e.key === 'Enter' && navigate(`/search?city=${encodeURIComponent(location)}`)} placeholder={t.location} className="w-full bg-transparent text-sm font-medium outline-none placeholder:text-[#9aa49b]" /></div><button onClick={() => navigate(`/search?category=${encodeURIComponent(service)}&city=${encodeURIComponent(location)}`)} className="btn-primary flex items-center justify-center gap-2 rounded-xl px-5 py-3 text-sm font-bold">{t.find}<ArrowRight size={16}/></button></div> }

function HomePage({ t }: { t: typeof copy.en; language: Language }) { const [faq, setFaq] = useState(0); const faqs = ['What is KaamWale?','How do I find a professional?','Are professionals verified?','Can I contact a professional directly?','How do reviews work?']; return <main><section className="warm-grid relative overflow-hidden"><div className="mx-auto grid max-w-[1240px] gap-14 px-5 pb-20 pt-16 lg:grid-cols-[1.1fr_.9fr] lg:items-center lg:px-8 lg:pb-28 lg:pt-24"><div className="fade-up"><div className="mb-6 inline-flex items-center gap-2 rounded-full border border-[#dedbd1] bg-[#fffdf9]/70 px-3 py-1.5 text-xs font-bold uppercase tracking-[.16em] text-[#de6b35]"><span className="h-1.5 w-1.5 rounded-full bg-[#de6b35]"/> Local help, made easy</div><h1 className="heading max-w-2xl text-5xl font-extrabold leading-[1.02] text-[#193c2b] dark:text-[#eff7ef] sm:text-6xl lg:text-[76px]">{t.hero}</h1><p className="muted mt-6 max-w-xl text-base leading-7 sm:text-lg">{t.heroSub}</p><div className="mt-9"><SearchBox t={t}/><div className="mt-4 flex items-center gap-2 text-xs font-medium text-[#7a857c]"><ShieldCheck size={15} className="text-[#2e8b62]"/> Trusted profiles. Local service. No guesswork.</div></div></div><div className="relative hidden min-h-[420px] lg:block"><div className="absolute right-4 top-10 h-[320px] w-[320px] rounded-[40%_60%_55%_45%] bg-[#e9c46a]/35 blur-[1px]"/><div className="absolute right-14 top-2 h-[370px] w-[340px] rounded-[48%_52%_40%_60%] bg-[#de6b35] opacity-90"/><div className="absolute right-24 top-16 h-[320px] w-[280px] rounded-[45%_55%_60%_40%] bg-[#193c2b]"/><div className="absolute right-[120px] top-[105px] flex h-36 w-36 items-center justify-center rounded-full bg-[#f6bc55] text-[#193c2b] shadow-2xl"><Wrench size={64} strokeWidth={1.3}/></div><div className="float surface absolute bottom-8 left-8 rounded-2xl p-4 shadow-xl"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-full bg-[#d8eee1] text-[#24724d]"><Check size={20}/></span><div><p className="text-sm font-bold text-[#193c2b]">Verified professional</p><p className="muted text-xs">Ready to help near you</p></div></div></div><div className="float surface absolute right-0 top-20 rounded-2xl p-3 shadow-xl" style={{animationDelay:'1s'}}><div className="flex items-center gap-2"><Star size={16} fill="#f6bc55" className="text-[#f6bc55]"/><span className="text-sm font-bold">4.9</span><span className="muted text-xs">average rating</span></div></div></div></div></section><section className="mx-auto max-w-[1240px] px-5 py-16 lg:px-8 lg:py-24"><SectionHeading eyebrow="START HERE" title={t.categories} sub={t.categoriesSub}/><div className="mt-10 grid grid-cols-2 gap-3 sm:grid-cols-4 lg:grid-cols-8">{categories.slice(0,8).map(([name,slug,desc,icon],i) => <Link to={`/search?category=${slug}`} key={slug} className="surface group rounded-2xl p-4 transition hover:-translate-y-1 hover:border-[#de6b35]/50 hover:shadow-lg"><div className={`mb-7 flex h-10 w-10 items-center justify-center rounded-xl ${i%2 ? 'bg-[#e3eee6] text-[#26714b]' : 'bg-[#fff0e9] text-[#de6b35]'}`}><Icon name={icon}/></div><p className="text-sm font-bold text-[#193c2b] dark:text-[#eff7ef]">{name}</p><p className="muted mt-1 line-clamp-2 text-[11px] leading-4">{desc}</p></Link>)}</div><div className="mt-7 text-center"><Link to="/categories" className="inline-flex items-center gap-2 text-sm font-bold text-[#de6b35]">{t.viewAll}<ArrowRight size={16}/></Link></div></section><section id="how" className="bg-[#193c2b] text-white"><div className="mx-auto max-w-[1240px] px-5 py-16 lg:px-8 lg:py-24"><SectionHeading dark eyebrow="THREE SIMPLE STEPS" title={t.how} sub="From searching to sorted, KaamWale keeps it easy."/><div className="mt-12 grid gap-5 md:grid-cols-3">{[['01','Search','Choose the service you need and tell us where you are.',Search],['02','Choose','Compare ratings, experience and availability.',Users],['03','Connect','Call, WhatsApp or request a service directly.',MessageCircle]].map(([num,title,text,StepIcon]) => <div key={num as string} className="rounded-2xl border border-white/10 bg-white/[.06] p-6"><span className="text-sm font-bold text-[#f6bc55]">{num as string}</span><div className="my-8 flex h-12 w-12 items-center justify-center rounded-xl bg-[#de6b35] text-white">{(() => { const C = StepIcon as typeof Search; return <C size={23}/> })()}</div><h3 className="heading text-2xl font-bold">{title as string}</h3><p className="mt-2 text-sm leading-6 text-[#b8cbbb]">{text as string}</p></div>)}</div></div></section><section className="mx-auto max-w-[1240px] px-5 py-16 lg:px-8 lg:py-24"><SectionHeading eyebrow="HANDPICKED FOR YOU" title={t.featured} sub="Meet some of the highly-rated people serving local communities."/><div className="mt-10 grid gap-5 md:grid-cols-2 lg:grid-cols-4">{professionals.slice(0,4).map(p => <ProfessionalCard key={p.id} professional={p}/>)}</div><div className="mt-8 text-center"><Link to="/search" className="btn-dark inline-flex items-center gap-2 rounded-xl px-5 py-3 text-sm font-bold">Explore professionals <ArrowRight size={16}/></Link></div></section><section className="bg-[#eeece5] dark:bg-[#17201b]"><div className="mx-auto max-w-[1240px] px-5 py-16 lg:px-8 lg:py-24"><SectionHeading eyebrow="THE KAAMWALE PROMISE" title={t.why} sub="A better way to get everyday work done."/><div className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-5">{[['Verified professionals',BadgeCheck,'Profiles with a verification process behind them.'],['Nearby services',MapPin,'Discover people serving your area.'],['Real reviews',Star,'Make choices with more confidence.'],['Easy contact',Phone,'Call, WhatsApp or send a request.'],['Many categories',BriefcaseBusiness,'One platform for everyday local work.']].map(([title,Feature,desc]) => <div key={title as string} className="surface rounded-2xl p-5"><div className="mb-7 flex h-10 w-10 items-center justify-center rounded-xl bg-[#d8eee1] text-[#26714b]">{(() => { const C=Feature as typeof BadgeCheck; return <C size={20}/> })()}</div><h3 className="text-sm font-bold text-[#193c2b] dark:text-white">{title as string}</h3><p className="muted mt-2 text-xs leading-5">{desc as string}</p></div>)}</div></div></section><section className="mx-auto max-w-[1240px] px-5 py-16 lg:px-8 lg:py-24"><div className="grid gap-10 lg:grid-cols-[.8fr_1.2fr] lg:items-center"><div><span className="text-xs font-bold uppercase tracking-[.18em] text-[#de6b35]">FROM THE COMMUNITY</span><h2 className="heading mt-4 text-4xl font-extrabold leading-tight text-[#193c2b] dark:text-white">People who get things done, together.</h2></div><div className="grid gap-4 sm:grid-cols-2"><div className="surface rounded-2xl p-6"><div className="mb-5 flex gap-1 text-[#f6bc55]">{[1,2,3,4,5].map(i=><Star key={i} size={15} fill="currentColor"/>)}</div><p className="text-base font-semibold leading-7 text-[#193c2b] dark:text-white">“KaamWale se mujhe apne area mein electrician bahut easily mil gaya. Rakesh ji arrived on time and fixed the issue quickly.”</p><p className="muted mt-5 text-xs font-semibold">Demo testimonial · Jaipur</p></div><div className="surface rounded-2xl p-6"><div className="mb-5 flex gap-1 text-[#f6bc55]">{[1,2,3,4,5].map(i=><Star key={i} size={15} fill="currentColor"/>)}</div><p className="text-base font-semibold leading-7 text-[#193c2b] dark:text-white">“The service request made it easy to explain what I needed before the professional called me.”</p><p className="muted mt-5 text-xs font-semibold">Demo testimonial · Delhi</p></div></div></div></section><section className="mx-auto max-w-3xl px-5 pb-16 lg:pb-24"><SectionHeading eyebrow="GOOD TO KNOW" title="Frequently asked questions" sub="A few quick answers before you get started."/><div className="mt-8 divide-y divide-[#dedbd1] dark:divide-[#35493b]">{faqs.map((q,i)=><div key={q}><button onClick={()=>setFaq(faq===i?-1:i)} className="flex w-full items-center justify-between py-5 text-left text-sm font-bold text-[#193c2b] dark:text-white"><span>{q}</span><ChevronDown size={18} className={`transition ${faq===i?'rotate-180 text-[#de6b35]':''}`}/></button>{faq===i&&<p className="pb-5 text-sm leading-6 text-[#657168] dark:text-[#a8b7aa]">KaamWale is a local services marketplace designed to help you discover, compare and connect with professionals. Demo content is shown here while real profiles and reviews come from the connected marketplace.</p>}</div>)}</div></section><section className="mx-5 mb-16 overflow-hidden rounded-3xl bg-[#de6b35] lg:mx-auto lg:max-w-[1200px]"><div className="flex flex-col items-start justify-between gap-7 px-7 py-10 sm:flex-row sm:items-center sm:px-12 lg:py-14"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-white/70">FOR LOCAL PROFESSIONALS</p><h2 className="heading mt-3 max-w-lg text-3xl font-extrabold text-white sm:text-4xl">{t.cta}</h2><p className="mt-3 max-w-lg text-sm leading-6 text-white/80">Are you an electrician, plumber, cleaner, carpenter or another local professional? Connect with customers near you.</p></div><Link to="/professional/register" className="flex shrink-0 items-center gap-2 rounded-xl bg-white px-5 py-3 text-sm font-bold text-[#de6b35]">Join KaamWale <ArrowRight size={16}/></Link></div></section></main> }

function SectionHeading({ eyebrow, title, sub, dark=false }: { eyebrow:string; title:string; sub:string; dark?:boolean }) { return <div><span className={`text-xs font-bold uppercase tracking-[.18em] ${dark?'text-[#f6bc55]':'text-[#de6b35]'}`}>{eyebrow}</span><h2 className={`heading mt-3 text-3xl font-extrabold ${dark?'text-white':'text-[#193c2b] dark:text-white'} sm:text-4xl`}>{title}</h2><p className={`mt-3 max-w-xl text-sm leading-6 ${dark?'text-[#b8cbbb]':'muted'}`}>{sub}</p></div> }

function ProfessionalCard({ professional:p, compact=false }: { professional:Professional; compact?:boolean }) { const [saved,setSaved]=useState(false); return <article className="surface group rounded-2xl p-4 transition hover:-translate-y-1 hover:shadow-[0_15px_35px_rgba(25,60,43,.1)]"><div className="flex items-start justify-between"><Link to={`/professional/${p.id}`} className="flex items-center gap-3"><div className="flex h-12 w-12 items-center justify-center rounded-full text-sm font-bold text-white" style={{background:p.color}}>{p.initials}</div><div><h3 className="text-sm font-bold text-[#193c2b] dark:text-white">{p.name}</h3><p className="muted mt-0.5 text-xs">{p.category}</p></div></Link><button onClick={()=>setSaved(!saved)} aria-label="Save professional" className={`${saved?'text-[#de6b35]':'text-[#a4ada5]'} p-1 transition hover:scale-110`}><Heart size={18} fill={saved?'currentColor':'none'}/></button></div><div className="mt-5 flex items-center gap-2"><span className="flex items-center gap-1 text-xs font-bold text-[#193c2b] dark:text-white"><Star size={14} fill="#f6bc55" className="text-[#f6bc55]"/> {p.rating}</span><span className="muted text-xs">({p.reviews} reviews)</span>{p.verified&&<span className="ml-auto flex items-center gap-1 text-[10px] font-bold text-[#2e8b62]"><BadgeCheck size={14}/> Verified</span>}</div>{!compact&&<><div className="muted mt-3 flex items-center gap-1.5 text-xs"><MapPin size={14}/>{p.area}, {p.city}</div><div className="mt-3 flex items-center justify-between border-t border-[#ece9e1] pt-3 dark:border-[#2e3d33]"><span className={`text-xs font-semibold ${p.availability==='Available today'?'text-[#2e8b62]':'text-[#9a6c2a]'}`}><span className="mr-1">●</span>{p.availability}</span><span className="text-xs font-bold text-[#193c2b] dark:text-white">From ₹{p.price}</span></div><div className="mt-4 grid grid-cols-2 gap-2"><Link to={`/professional/${p.id}`} className="pill rounded-lg py-2 text-center text-xs font-bold text-[#193c2b] dark:text-white">View profile</Link><Link to={`/professional/${p.id}?request=true`} className="btn-primary rounded-lg py-2 text-center text-xs font-bold">Request service</Link></div></>}</article> }

function CategoriesPage({ t }: { t: typeof copy.en }) { return <main className="mx-auto max-w-[1240px] px-5 py-14 lg:px-8 lg:py-20"><SectionHeading eyebrow="EXPLORE LOCAL SERVICES" title="Find the right help for every kind of work." sub="Browse categories, compare professionals and get your next task moving."/><div className="mt-12 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{categories.map(([name,slug,desc,icon],i)=><Link key={slug} to={`/search?category=${slug}`} className="surface group flex min-h-[185px] flex-col rounded-2xl p-5 transition hover:-translate-y-1 hover:border-[#de6b35]/50 hover:shadow-lg"><div className={`flex h-11 w-11 items-center justify-center rounded-xl ${i%2?'bg-[#e3eee6] text-[#26714b]':'bg-[#fff0e9] text-[#de6b35]'}`}><Icon name={icon}/></div><h3 className="mt-7 text-base font-bold text-[#193c2b] dark:text-white">{name}</h3><p className="muted mt-2 flex-1 text-xs leading-5">{desc}</p><span className="mt-4 flex items-center gap-1 text-xs font-bold text-[#de6b35]">Find professionals <ArrowRight size={14}/></span></Link>)}</div></main> }

function SearchPage() { const [params] = useSearchParams(); const initialCategory=params.get('category')||''; const initialCity=params.get('city')||''; const [category,setCategory]=useState(initialCategory); const [city,setCity]=useState(initialCity); const [verified,setVerified]=useState(false); const [filters,setFilters]=useState(false); const results=useMemo(()=>professionals.filter(p=>(!category||p.category.toLowerCase().includes(category.toLowerCase())||p.categorySlug===category.toLowerCase())&&(!city||p.city.toLowerCase().includes(city.toLowerCase())||p.area.toLowerCase().includes(city.toLowerCase()))&&(verified?p.verified:true)),[category,city,verified]); return <main className="mx-auto max-w-[1240px] px-5 py-10 lg:px-8 lg:py-16"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><span className="text-xs font-bold uppercase tracking-[.18em] text-[#de6b35]">DISCOVER LOCAL TALENT</span><h1 className="heading mt-3 text-4xl font-extrabold text-[#193c2b] dark:text-white">{category ? `${category} near ${city||'you'}` : 'Professionals near you'}</h1><p className="muted mt-2 text-sm">{results.length} professionals ready to help</p></div><button onClick={()=>setFilters(true)} className="pill flex items-center justify-center gap-2 rounded-xl px-4 py-3 text-sm font-bold text-[#193c2b] dark:text-white lg:hidden"><Filter size={16}/> Filters</button></div><div className="mt-8 flex flex-col gap-8 lg:flex-row"><aside className={`${filters?'fixed inset-0 z-50 flex items-end bg-black/30':'hidden'} lg:relative lg:inset-auto lg:z-auto lg:flex lg:w-64 lg:shrink-0 lg:bg-transparent`}><div className="surface w-full rounded-t-3xl p-5 lg:sticky lg:top-24 lg:rounded-2xl"><div className="mb-5 flex items-center justify-between"><h2 className="text-sm font-bold text-[#193c2b] dark:text-white">Refine your search</h2><button onClick={()=>setFilters(false)} className="lg:hidden"><X size={18}/></button></div><label className="mb-2 block text-xs font-bold text-[#657168]">Service category</label><select value={category} onChange={e=>setCategory(e.target.value)} className="mb-5 w-full rounded-xl border border-[#dedbd1] bg-transparent px-3 py-3 text-sm outline-none"><option value="">All categories</option>{categories.map(([n,s])=><option key={s} value={s}>{n}</option>)}</select><label className="mb-2 block text-xs font-bold text-[#657168]">City or area</label><div className="mb-5 flex items-center rounded-xl border border-[#dedbd1] px-3"><MapPin size={15} className="text-[#de6b35]"/><input value={city} onChange={e=>setCity(e.target.value)} placeholder="Jaipur, Delhi..." className="w-full bg-transparent px-2 py-3 text-sm outline-none"/></div><div className="flex items-center justify-between border-t border-[#ece9e1] py-4 dark:border-[#2e3d33]"><span className="text-sm font-semibold text-[#193c2b] dark:text-white">Verified only</span><button onClick={()=>setVerified(!verified)} className={`h-6 w-11 rounded-full p-1 transition ${verified?'bg-[#2e8b62]':'bg-[#c9d0ca]'}`}><span className={`block h-4 w-4 rounded-full bg-white transition ${verified?'translate-x-5':''}`}/></button></div><p className="muted border-t border-[#ece9e1] pt-4 text-xs leading-5 dark:border-[#2e3d33]">More filters for distance, rating, price and availability will appear here as your search grows.</p><button onClick={()=>setFilters(false)} className="btn-primary mt-5 w-full rounded-xl py-3 text-sm font-bold lg:hidden">Show {results.length} results</button></div></aside><div className="grid flex-1 gap-4 md:grid-cols-2 xl:grid-cols-3">{results.length?results.map(p=><ProfessionalCard key={p.id} professional={p}/>):<div className="surface col-span-full rounded-2xl p-12 text-center"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-[#fff0e9] text-[#de6b35]"><Search size={24}/></div><h2 className="mt-5 text-lg font-bold text-[#193c2b] dark:text-white">No professionals found in this area yet.</h2><p className="muted mx-auto mt-2 max-w-sm text-sm">Try another category or a nearby city to discover more local help.</p><button onClick={()=>{setCategory('');setCity('');setVerified(false)}} className="btn-dark mt-6 rounded-xl px-5 py-3 text-sm font-bold">Clear filters</button></div>}</div></div></main> }

function ProfessionalPage() { const { id } = useParamsSafe(); const p=professionals.find(item=>item.id===id)||professionals[0]; const [request,setRequest]=useState(false); return <main className="mx-auto max-w-[1100px] px-5 py-10 lg:px-8 lg:py-16"><Link to="/search" className="muted inline-flex items-center gap-2 text-sm font-semibold"><ChevronLeft size={16}/> Back to results</Link><div className="mt-8 grid gap-6 lg:grid-cols-[1fr_320px]"><div><div className="surface rounded-3xl p-6 sm:p-8"><div className="flex flex-col gap-5 sm:flex-row sm:items-start"><div className="flex h-24 w-24 shrink-0 items-center justify-center rounded-3xl text-2xl font-bold text-white" style={{background:p.color}}>{p.initials}</div><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><h1 className="heading text-3xl font-extrabold text-[#193c2b] dark:text-white">{p.name}</h1>{p.verified&&<BadgeCheck size={21} className="text-[#2e8b62]"/>}</div><p className="muted mt-1">{p.category} · {p.area}, {p.city}</p><div className="mt-4 flex flex-wrap items-center gap-4 text-sm"><span className="flex items-center gap-1 font-bold"><Star size={16} fill="#f6bc55" className="text-[#f6bc55]"/>{p.rating} <span className="muted font-normal">({p.reviews} reviews)</span></span><span className="muted flex items-center gap-1"><BriefcaseBusiness size={15}/>{p.experience} years experience</span></div></div></div><div className="mt-7 flex flex-wrap gap-3"><a href={`tel:${p.name}`} className="btn-dark flex items-center gap-2 rounded-xl px-4 py-3 text-sm font-bold"><Phone size={16}/> Call now</a><a href={`https://wa.me/919999999999`} className="flex items-center gap-2 rounded-xl bg-[#d8eee1] px-4 py-3 text-sm font-bold text-[#26714b]"><MessageCircle size={16}/> WhatsApp</a><button onClick={()=>setRequest(true)} className="btn-primary flex items-center gap-2 rounded-xl px-4 py-3 text-sm font-bold"><CalendarDays size={16}/> Request service</button></div></div><div className="surface mt-5 rounded-3xl p-6 sm:p-8"><h2 className="heading text-xl font-bold text-[#193c2b] dark:text-white">About {p.name.split(' ')[0]}</h2><p className="muted mt-3 text-sm leading-7">{p.about} With a focus on transparent communication and quality work, every job starts with understanding what you need.</p><div className="mt-8 grid gap-3 sm:grid-cols-3"><Trust icon={ShieldCheck} title="Identity verified" show={p.verified}/><Trust icon={Phone} title="Phone verified" show={p.verified}/><Trust icon={MapPin} title={`${p.area} service area`} show/></div><h2 className="heading mt-10 text-xl font-bold text-[#193c2b] dark:text-white">Services offered</h2><div className="mt-4 flex flex-wrap gap-2">{['Inspection & diagnosis','Repair and replacement','Installation','Emergency service'].map(s=><span key={s} className="pill rounded-full px-3 py-2 text-xs font-semibold text-[#657168]">{s}</span>)}</div><h2 className="heading mt-10 text-xl font-bold text-[#193c2b] dark:text-white">Customer reviews</h2><div className="mt-4 rounded-2xl bg-[#f4f2ec] p-5 dark:bg-[#1c2820]"><div className="flex items-center gap-1 text-[#f6bc55]">{[1,2,3,4,5].map(i=><Star key={i} size={15} fill="currentColor"/>)}</div><p className="mt-3 text-sm leading-6 text-[#193c2b] dark:text-white">“Very professional, arrived on time and explained the work clearly. Would definitely recommend.”</p><p className="muted mt-3 text-xs font-semibold">Demo review · Verified service request</p></div></div></div><aside><div className="surface sticky top-24 rounded-3xl p-6"><div className="flex items-center justify-between"><span className="muted text-sm">Starting from</span><span className="heading text-2xl font-extrabold text-[#193c2b] dark:text-white">₹{p.price}</span></div><div className="mt-5 rounded-2xl bg-[#d8eee1] p-4 text-sm font-semibold text-[#26714b]"><div className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-[#2e8b62]"/>{p.availability}</div><p className="mt-2 text-xs font-normal leading-5 text-[#26714b]/80">Usually responds within 30 minutes.</p></div><button onClick={()=>setRequest(true)} className="btn-primary mt-5 w-full rounded-xl py-3.5 text-sm font-bold">Request a service</button><p className="muted mt-4 text-center text-xs">No payment required to send a request.</p></div></aside></div>{request&&<RequestModal professional={p} close={()=>setRequest(false)}/>}</main> }
function Trust({icon:TrustIcon,title,show}:{icon:typeof ShieldCheck;title:string;show:boolean}){return <div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#d8eee1] text-[#26714b]"><TrustIcon size={17}/></div><div><p className="text-xs font-bold text-[#193c2b] dark:text-white">{title}</p><p className="muted mt-0.5 text-[10px]">{show?'Confirmed':'Not provided'}</p></div></div>}
function RequestModal({ professional, close }: { professional:Professional; close:()=>void }) { const [sent,setSent]=useState(false); return <div className="fixed inset-0 z-50 flex items-end justify-center bg-[#193c2b]/40 p-0 sm:items-center sm:p-5"><div className="surface max-h-[90vh] w-full max-w-lg overflow-auto rounded-t-3xl p-6 sm:rounded-3xl sm:p-8"><div className="flex items-start justify-between"><div><span className="text-xs font-bold uppercase tracking-[.16em] text-[#de6b35]">SERVICE REQUEST</span><h2 className="heading mt-2 text-2xl font-extrabold text-[#193c2b] dark:text-white">Request {professional.category.toLowerCase()}</h2><p className="muted mt-1 text-sm">{professional.name} · {professional.area}</p></div><button onClick={close} className="muted rounded-lg p-2 hover:bg-[#eeece5]"><X size={19}/></button></div>{sent?<div className="py-12 text-center"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-[#d8eee1] text-[#26714b]"><Check size={25}/></div><h3 className="mt-5 text-xl font-bold text-[#193c2b] dark:text-white">Your service request has been sent.</h3><p className="muted mt-2 text-sm">{professional.name} will get back to you soon.</p><button onClick={close} className="btn-dark mt-7 rounded-xl px-5 py-3 text-sm font-bold">Done</button></div>:<form onSubmit={e=>{e.preventDefault();setSent(true)}} className="mt-7 space-y-4"><Field label="What do you need help with?" placeholder="e.g. Fan repair, pipe leakage" required/><div className="grid gap-4 sm:grid-cols-2"><Field label="Preferred date" type="date"/><Field label="Preferred time" type="time"/></div><Field label="Your address" placeholder="House no., street and area" required/><div className="grid gap-4 sm:grid-cols-2"><Field label="City" placeholder="Jaipur" required/><Field label="Pincode" placeholder="302019" required/></div><Field label="Additional notes" placeholder="Anything else the professional should know?" area/><button className="btn-primary w-full rounded-xl py-3.5 text-sm font-bold">Send request</button></form>}</div></div> }
function Field({label,placeholder,type='text',required=false,area=false}:{label:string;placeholder?:string;type?:string;required?:boolean;area?:boolean}){return <label className="block"><span className="mb-1.5 block text-xs font-bold text-[#657168]">{label}</span>{area?<textarea rows={3} placeholder={placeholder} className="w-full resize-none rounded-xl border border-[#dedbd1] bg-transparent px-3 py-3 text-sm outline-none focus:border-[#de6b35]"/>:<input type={type} placeholder={placeholder} required={required} className="w-full rounded-xl border border-[#dedbd1] bg-transparent px-3 py-3 text-sm outline-none focus:border-[#de6b35]"/>}</label>}
function useParamsSafe(){const location=useLocation(); return {id:location.pathname.split('/').pop()||'p1'};}

function AuthPage({ professional, register=false }: { professional:boolean; register?:boolean }) { const [mode,setMode]=useState(register?'register':'login'); const [error,setError]=useState(''); const [loading,setLoading]=useState(false); const navigate=useNavigate(); const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setLoading(true);setError('');const form=new FormData(e.currentTarget);const email=String(form.get('email'));const password=String(form.get('password'));if(supabase){const result=mode==='register'?await supabase.auth.signUp({email,password,options:{data:{full_name:form.get('name'),role:professional?'professional':'customer'}}}):await supabase.auth.signInWithPassword({email,password});if(result.error){setError('We could not complete that request. Please check your details and try again.');setLoading(false);return;}}setLoading(false);navigate(professional?'/professional/dashboard':'/dashboard')}; return <main className="mx-auto grid min-h-[680px] max-w-[1100px] gap-10 px-5 py-12 lg:grid-cols-[.9fr_1.1fr] lg:items-center lg:px-8"><div className="hidden rounded-3xl bg-[#193c2b] p-10 text-white lg:block"><span className="text-xs font-bold uppercase tracking-[.18em] text-[#f6bc55]">{professional?'FOR LOCAL PROFESSIONALS':'WELCOME TO KAAMWALE'}</span><h1 className="heading mt-5 text-5xl font-extrabold leading-tight">{professional?'Apna kaam, apni pehchaan.':'Everyday work, made easier.'}</h1><p className="mt-5 max-w-sm text-sm leading-7 text-[#b8cbbb]">{professional?'Showcase your skills and connect with customers who need your work.':'Find trusted people for the work that matters at home.'}</p><div className="mt-16 flex items-center gap-3 text-sm font-semibold"><ShieldCheck className="text-[#f6bc55]" size={20}/> Built around trust and local service</div></div><div className="surface mx-auto w-full max-w-md rounded-3xl p-6 sm:p-9"><div className="mb-8"><span className="text-xs font-bold uppercase tracking-[.18em] text-[#de6b35]">{professional?'PROFESSIONAL ACCOUNT':'YOUR ACCOUNT'}</span><h1 className="heading mt-3 text-3xl font-extrabold text-[#193c2b] dark:text-white">{mode==='login'?'Welcome back':'Create your account'}</h1><p className="muted mt-2 text-sm">{mode==='login'?'Log in to continue to KaamWale.':'Start with a few details. You can complete your profile later.'}</p></div><form onSubmit={submit} className="space-y-4">{mode==='register'&&<Field label="Full name" placeholder="Your name" required/>}<Field label="Email address" type="email" placeholder="you@example.com" required/><Field label="Password" type="password" placeholder="At least 6 characters" required/>{mode==='register'&&<><Field label="Mobile number" placeholder="10-digit mobile number" required/><Field label="City" placeholder="Jaipur" required/></>}{error&&<p className="rounded-xl bg-[#fff0e9] px-3 py-2 text-xs font-semibold text-[#b54d22]">{error}</p>}<button disabled={loading} className="btn-primary w-full rounded-xl py-3.5 text-sm font-bold">{loading?'Please wait...':mode==='login'?'Log in':'Create account'}</button></form><div className="mt-6 text-center text-sm"><span className="muted">{mode==='login'?"Don't have an account?":"Already have an account?"}</span> <button onClick={()=>setMode(mode==='login'?'register':'login')} className="font-bold text-[#de6b35]">{mode==='login'?'Register':'Log in'}</button></div>{!professional&&<Link to="/professional/register" className="mt-6 flex items-center justify-center gap-2 rounded-xl bg-[#eeece5] py-3 text-xs font-bold text-[#193c2b] dark:bg-[#1c2820] dark:text-white"><BriefcaseBusiness size={15}/> Are you a professional? Join KaamWale</Link>}</div></main> }

function Dashboard({activeTab,setActiveTab}:{activeTab:string;setActiveTab:(tab:string)=>void}){return <DashboardShell professional={false}><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><span className="text-xs font-bold uppercase tracking-[.18em] text-[#de6b35]">CUSTOMER DASHBOARD</span><h1 className="heading mt-3 text-3xl font-extrabold text-[#193c2b] dark:text-white">Good morning, there.</h1><p className="muted mt-2 text-sm">Here is what is happening with your local services.</p></div><Link to="/search" className="btn-primary inline-flex items-center justify-center gap-2 rounded-xl px-4 py-3 text-sm font-bold"><Search size={16}/> Find a professional</Link></div><div className="mt-8 grid gap-4 sm:grid-cols-3">{[['Active requests','2',Clock3],['Completed services','8',Check],['Saved professionals','5',Heart]].map(([label,value,StatIcon])=><div key={label as string} className="surface rounded-2xl p-5"><div className="flex items-center justify-between"><span className="muted text-xs font-semibold">{label as string}</span>{(() => {const C=StatIcon as typeof Check;return <C size={17} className="text-[#de6b35]"/>})()}</div><p className="heading mt-5 text-3xl font-extrabold text-[#193c2b] dark:text-white">{value as string}</p></div>)}</div><div className="surface mt-5 rounded-2xl p-6"><div className="flex items-center justify-between"><h2 className="heading text-lg font-bold text-[#193c2b] dark:text-white">Recent requests</h2><button onClick={()=>setActiveTab('My Requests')} className="text-xs font-bold text-[#de6b35]">View all</button></div><div className="mt-5 space-y-3">{[['AC service','Vikram Singh','Accepted','Tomorrow, 10:00 AM'],['Kitchen plumbing','Mohammed Salim','Completed','12 Aug 2026']].map(([service,name,status,date])=><div key={service} className="flex flex-col justify-between gap-3 rounded-xl bg-[#f4f2ec] p-4 dark:bg-[#1c2820] sm:flex-row sm:items-center"><div><p className="text-sm font-bold text-[#193c2b] dark:text-white">{service}</p><p className="muted mt-1 text-xs">{name} · {date}</p></div><span className={`w-fit rounded-full px-3 py-1 text-[11px] font-bold ${status==='Accepted'?'bg-[#d8eee1] text-[#26714b]':'bg-[#e8e5dd] text-[#657168]'}`}>{status}</span></div>)}</div></div></DashboardShell>}
function DashboardShell({professional,children}:{professional:boolean;children:ReactNode}){const navigate=useNavigate();return <main className="mx-auto max-w-[1240px] px-5 py-8 lg:px-8 lg:py-12"><div className="mb-6 flex items-center justify-between"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#193c2b] text-[#f6bc55]"><CircleUserRound size={21}/></div><div><p className="text-sm font-bold text-[#193c2b] dark:text-white">{professional?'Professional account':'Your account'}</p><p className="muted mt-0.5 text-[11px]">Jaipur, India</p></div></div><button onClick={()=>navigate('/')} className="flex items-center gap-2 rounded-lg px-3 py-2 text-xs font-semibold text-[#657168] hover:bg-[#eeece5] dark:hover:bg-[#1c2820]"><LogIn size={15}/> Log out</button></div><div className="min-w-0">{children}</div></main>}
function ProfessionalDashboard({activeTab,setActiveTab}:{activeTab:string;setActiveTab:(tab:string)=>void}){return <DashboardShell professional><span className="text-xs font-bold uppercase tracking-[.18em] text-[#de6b35]">PROFESSIONAL SPACE</span><h1 className="heading mt-3 text-3xl font-extrabold text-[#193c2b] dark:text-white">Your work, in one place.</h1><p className="muted mt-2 text-sm">Manage requests, keep your profile fresh and stay ready for the next customer.</p><div className="mt-8 grid gap-4 sm:grid-cols-3">{[['Profile views','184',Users],['New requests','6',Bell],['Average rating','4.8',Star]].map(([label,value,StatIcon])=><div key={label as string} className="surface rounded-2xl p-5"><span className="muted text-xs font-semibold">{label as string}</span><div className="mt-4 flex items-end justify-between"><p className="heading text-3xl font-extrabold text-[#193c2b] dark:text-white">{value as string}</p>{(() => {const C=StatIcon as typeof Star;return <C size={18} className="text-[#de6b35]" fill={label==='Average rating'?'#f6bc55':'none'}/>})()}</div></div>)}</div><div className="surface mt-5 rounded-2xl p-6"><div className="flex items-center justify-between"><h2 className="heading text-lg font-bold text-[#193c2b] dark:text-white">Incoming service requests</h2><span className="rounded-full bg-[#fff0e9] px-3 py-1 text-[11px] font-bold text-[#de6b35]">6 new</span></div>{[['Fan installation','Priya Mehta','Vaishali Nagar','Today, 5:00 PM'],['AC not cooling','Rahul Gupta','Mansarovar','Tomorrow, 11:30 AM']].map(item=><div key={item[0]} className="mt-4 flex flex-col justify-between gap-4 rounded-xl bg-[#f4f2ec] p-4 dark:bg-[#1c2820] sm:flex-row sm:items-center"><div><p className="text-sm font-bold text-[#193c2b] dark:text-white">{item[0]}</p><p className="muted mt-1 text-xs">{item[1]} · {item[2]} · {item[3]}</p></div><div className="flex gap-2"><button className="rounded-lg bg-[#d8eee1] px-3 py-2 text-xs font-bold text-[#26714b]">Accept</button><button className="pill rounded-lg px-3 py-2 text-xs font-bold text-[#657168]">View</button></div></div>)}</div></DashboardShell>}
function AdminDashboard({activeTab,setActiveTab}:{activeTab:string;setActiveTab:(tab:string)=>void}){return <DashboardShell professional><span className="text-xs font-bold uppercase tracking-[.18em] text-[#de6b35]">ADMIN CONTROL</span><h1 className="heading mt-3 text-3xl font-extrabold text-[#193c2b] dark:text-white">Platform overview.</h1><p className="muted mt-2 text-sm">A clear view of marketplace activity and trust operations.</p><div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[['Total users','1,248',Users],['Professionals','386',BriefcaseBusiness],['Pending verification','12',ShieldCheck],['Total requests','2,406',CalendarDays]].map(([label,value,StatIcon])=><div key={label as string} className="surface rounded-2xl p-5"><div className="flex justify-between"><span className="muted text-xs font-semibold">{label as string}</span>{(() => {const C=StatIcon as typeof Users;return <C size={17} className="text-[#de6b35]"/>})()}</div><p className="heading mt-5 text-3xl font-extrabold text-[#193c2b] dark:text-white">{value as string}</p><p className="mt-2 text-[11px] font-semibold text-[#2e8b62]">+12% this month</p></div>)}</div><div className="mt-5 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><div className="surface rounded-2xl p-6"><div className="flex items-center justify-between"><h2 className="heading text-lg font-bold text-[#193c2b] dark:text-white">Verification queue</h2><span className="text-xs font-bold text-[#de6b35]">12 pending</span></div>{professionals.slice(0,4).map(p=><div key={p.id} className="flex items-center justify-between border-b border-[#ece9e1] py-4 last:border-0 dark:border-[#2e3d33]"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-full text-xs font-bold text-white" style={{background:p.color}}>{p.initials}</div><div><p className="text-sm font-bold text-[#193c2b] dark:text-white">{p.name}</p><p className="muted mt-0.5 text-xs">{p.category} · {p.city}</p></div></div><button className="rounded-lg bg-[#d8eee1] px-3 py-2 text-[11px] font-bold text-[#26714b]">Review</button></div>)}</div><div className="surface rounded-2xl p-6"><h2 className="heading text-lg font-bold text-[#193c2b] dark:text-white">Request activity</h2><div className="mt-6 flex h-40 items-end gap-3 border-b border-l border-[#dedbd1] px-4 pb-0 pt-4 dark:border-[#35493b]">{[45,65,42,78,58,90,72].map((height,i)=><div key={i} className="flex flex-1 flex-col justify-end"><div className="rounded-t-md bg-[#de6b35] opacity-80" style={{height:`${height}%`}}/></div>)}</div><div className="mt-3 flex justify-between text-[10px] text-[#9aa49b]"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span></div></div></div></DashboardShell>}

function InfoPage({title,eyebrow,text}:{title:string;eyebrow:string;text:string}){return <main className="mx-auto max-w-3xl px-5 py-20 lg:py-28"><span className="text-xs font-bold uppercase tracking-[.18em] text-[#de6b35]">{eyebrow}</span><h1 className="heading mt-4 text-5xl font-extrabold text-[#193c2b] dark:text-white">{title}</h1><p className="muted mt-7 text-lg leading-8">{text}</p><div className="surface mt-10 rounded-2xl p-6"><h2 className="heading text-xl font-bold text-[#193c2b] dark:text-white">A better local services experience</h2><p className="muted mt-3 text-sm leading-7">KaamWale is designed to make discovery clear, conversations easy and local work more visible. This content is ready to be expanded with your final business details.</p></div></main>}
function Footer({t}:{t:typeof copy.en}){return <footer className="border-t border-[#e7e3da] bg-[#eeece5] dark:border-[#28382e] dark:bg-[#17201b]"><div className="mx-auto max-w-[1240px] px-5 py-12 lg:px-8"><div className="grid gap-10 sm:grid-cols-2 lg:grid-cols-[1.4fr_1fr_1fr_1fr]"><div><Link to="/" className="flex items-center gap-2"><span className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#193c2b] text-[#f6bc55]"><Wrench size={18}/></span><span className="heading text-lg font-extrabold text-[#193c2b] dark:text-white">Kaam<span className="text-[#de6b35]">Wale</span></span></Link><p className="muted mt-4 max-w-xs text-sm leading-6">{t.hero}</p><div className="mt-5 flex gap-3 text-[#657168]"><Facebook size={16}/><Linkedin size={16}/><MessageCircle size={16}/></div></div><div><p className="mb-4 text-xs font-bold uppercase tracking-[.15em] text-[#193c2b] dark:text-white">Explore</p><div className="flex flex-col gap-3 text-sm text-[#657168]"><Link to="/">Home</Link><Link to="/categories">Categories</Link><Link to="/search">Find professionals</Link><Link to="/#how">How it works</Link></div></div><div><p className="mb-4 text-xs font-bold uppercase tracking-[.15em] text-[#193c2b] dark:text-white">For professionals</p><div className="flex flex-col gap-3 text-sm text-[#657168]"><Link to="/professional/register">Join KaamWale</Link><Link to="/professional/login">Professional login</Link><Link to="/professional/dashboard">Dashboard</Link></div></div><div><p className="mb-4 text-xs font-bold uppercase tracking-[.15em] text-[#193c2b] dark:text-white">Support</p><div className="flex flex-col gap-3 text-sm text-[#657168]"><Link to="/contact">Contact</Link><Link to="/about">About us</Link><Link to="/privacy">Privacy</Link><Link to="/terms">Terms</Link></div></div></div><div className="mt-12 flex flex-col justify-between gap-3 border-t border-[#dedbd1] pt-5 text-xs text-[#8a948c] dark:border-[#35493b] sm:flex-row"><span>© 2026 KaamWale. Demo marketplace experience.</span><span>Made for local work, with care.</span></div></div></footer>}

